<?php
declare(strict_types=1);

if (($_GET['api'] ?? '') !== '') {
    $action=$_GET['api'];
    if ($_SERVER['REQUEST_METHOD']==='POST') verify_csrf();
    if ($action==='setup-status') json_out(['needed'=>(int)$p->query('SELECT COUNT(*) FROM users')->fetchColumn()===0]);
    if ($action==='setup' && $_SERVER['REQUEST_METHOD']==='POST') {
        if ((int)$p->query('SELECT COUNT(*) FROM users')->fetchColumn()!==0) json_out(['error'=>'Setup is already complete.'],409);
        $name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pw=(string)($_POST['password']??'');
        if ($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<12) json_out(['error'=>'Enter a name, valid email, and password with at least 12 characters.'],422);
        $q=$p->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'super_admin')");$q->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);bump();json_out(['ok'=>true]);
    }
    if ($action==='login' && $_SERVER['REQUEST_METHOD']==='POST') {
        $email=strtolower(trim($_POST['email']??''));$q=$p->prepare('SELECT * FROM users WHERE email=? AND active=1');$q->execute([$email]);$u=$q->fetch();
        if (!$u||!password_verify((string)($_POST['password']??''),$u['password_hash'])) json_out(['error'=>'Email or password is incorrect.'],401);
        session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role'],'department'=>$u['department']];$_SESSION['csrf']=bin2hex(random_bytes(32));json_out(['ok'=>true]);
    }
    if ($action==='logout' && $_SERVER['REQUEST_METHOD']==='POST') { require_user();$_SESSION=[];session_regenerate_id(true);json_out(['ok'=>true]); }
    if ($action==='public-calendar') { $from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-t',strtotime($from.' +1 month'));$rooms=$p->query('SELECT id,name,location FROM rooms WHERE active=1 ORDER BY name')->fetchAll();json_out(['reservations'=>public_rows($from.' 00:00:00',date('Y-m-d',strtotime($to.' +1 day')).' 00:00:00'),'rooms'=>$rooms,'revision'=>(int)$p->query('SELECT revision FROM app_state')->fetchColumn()]); }
    if ($action==='request' && $_SERVER['REQUEST_METHOD']==='POST') {
        $name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$dept=trim($_POST['department']??'');$title=trim($_POST['title']??'');$details=trim($_POST['details']??'');$room=(int)($_POST['room_id']??0);$start=valid_datetime($_POST['start_at']??'');$end=valid_datetime($_POST['end_at']??'');$urgent=isset($_POST['urgent'])&&$_POST['urgent']==='1';
        if ($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$dept===''||$title===''||!$start||!$end||$room<1||$end<=$start) json_out(['error'=>'Complete all required fields with a valid time range.'],422);
        if ($start<new DateTimeImmutable('now -1 minute')) json_out(['error'=>'Choose a future time.'],422);
        if ($urgent && ($end->getTimestamp()-$start->getTimestamp())>1800) json_out(['error'=>'Urgent requests are limited to 30 minutes.'],422);
        $p->beginTransaction();try{$q=$p->prepare('SELECT id FROM rooms WHERE id=? AND active=1');$q->execute([$room]);if(!$q->fetch())throw new RuntimeException('That room is unavailable.');if(conflict($room,$start->format('Y-m-d H:i:s'),$end->format('Y-m-d H:i:s')))throw new RuntimeException('That time was just taken. Refresh the calendar and choose another slot.');$q=$p->prepare("INSERT INTO reservations(room_id,requester_name,requester_email,department,event_title,details,start_at,end_at,urgent,status) VALUES(?,?,?,?,?,?,?,?,?,'pending')");$q->execute([$room,$name,$email,$dept,$title,$details,$start->format('Y-m-d H:i:s'),$end->format('Y-m-d H:i:s'),$urgent?1:0]);$rev=bump();$p->commit();json_out(['ok'=>true,'message'=>'Request sent for staff approval.','revision'=>$rev]);}catch(Throwable $ex){if($p->inTransaction())$p->rollBack();json_out(['error'=>$ex->getMessage()],409);}
    }
    $me=require_user();
    if ($action==='bootstrap') { $rooms=$p->query('SELECT * FROM rooms ORDER BY name')->fetchAll();$q=$p->query("SELECT r.*,rm.name room_name FROM reservations r JOIN rooms rm ON rm.id=r.room_id ORDER BY r.start_at DESC LIMIT 500");$rows=$q->fetchAll();$users=$p->query('SELECT id,name,email,role,department,active,created_at FROM users ORDER BY id')->fetchAll();json_out(['user'=>$me,'rooms'=>$rooms,'reservations'=>$rows,'users'=>$users,'revision'=>(int)$p->query('SELECT revision FROM app_state')->fetchColumn()]); }
    if ($action==='change-password'&&$_SERVER['REQUEST_METHOD']==='POST') { $old=(string)($_POST['old_password']??'');$new=(string)($_POST['new_password']??'');$q=$p->prepare('SELECT password_hash FROM users WHERE id=?');$q->execute([$me['id']]);if(!password_verify($old,(string)$q->fetchColumn()))json_out(['error'=>'Current password is incorrect.'],401);if(strlen($new)<12)json_out(['error'=>'New password must be at least 12 characters.'],422);$q=$p->prepare('UPDATE users SET password_hash=? WHERE id=?');$q->execute([password_hash($new,PASSWORD_DEFAULT),$me['id']]);json_out(['ok'=>true]); }
    if ($action==='users'&&$_SERVER['REQUEST_METHOD']==='POST') { require_user();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$dept=trim($_POST['department']??'');$pw=(string)($_POST['password']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<12)json_out(['error'=>'Provide a name, valid email, and password of at least 12 characters.'],422);try{$q=$p->prepare("INSERT INTO users(name,email,password_hash,role,department) VALUES(?,?,?,'admin',?)");$q->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT),$dept]);bump();json_out(['ok'=>true]);}catch(Throwable){json_out(['error'=>'That email may already have an account.'],409);} }
    if ($action==='user-status'&&$_SERVER['REQUEST_METHOD']==='POST') { require_user();$id=(int)($_POST['id']??0);if($id===$me['id'])json_out(['error'=>'You cannot deactivate your own account.'],422);$q=$p->prepare("UPDATE users SET active=CASE WHEN active=1 THEN 0 ELSE 1 END WHERE id=? AND role='admin'");$q->execute([$id]);bump();json_out(['ok'=>true]); }
    if ($action==='review'&&$_SERVER['REQUEST_METHOD']==='POST') { $id=(int)($_POST['id']??0);$status=$_POST['status']??'';if(!in_array($status,['approved','rejected','cancelled'],true))json_out(['error'=>'Invalid status.'],422);$q=$p->prepare('SELECT * FROM reservations WHERE id=?');$q->execute([$id]);$r=$q->fetch();if(!$r)json_out(['error'=>'Request not found.'],404);if($status==='approved'&&conflict((int)$r['room_id'],$r['start_at'],$r['end_at'],$id))json_out(['error'=>'Another reservation now overlaps this time. Resolve the conflict first.'],409);$q=$p->prepare('UPDATE reservations SET status=?,reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP,rejection_reason=? WHERE id=?');$q->execute([$status,$me['id'],trim($_POST['reason']??''),$id]);bump();json_out(['ok'=>true]); }
    if ($action==='room'&&$_SERVER['REQUEST_METHOD']==='POST') { $name=trim($_POST['name']??'');$loc=trim($_POST['location']??'');$cap=max(1,(int)($_POST['capacity']??1));$id=(int)($_POST['id']??0);if($name==='')json_out(['error'=>'Room name is required.'],422);if($id){$q=$p->prepare('UPDATE rooms SET name=?,location=?,capacity=? WHERE id=?');$q->execute([$name,$loc,$cap,$id]);}else{$q=$p->prepare('INSERT INTO rooms(name,location,capacity) VALUES(?,?,?)');$q->execute([$name,$loc,$cap]);}bump();json_out(['ok'=>true]); }
    if ($action==='room-status'&&$_SERVER['REQUEST_METHOD']==='POST') { $id=(int)($_POST['id']??0);$q=$p->prepare('UPDATE rooms SET active=CASE WHEN active=1 THEN 0 ELSE 1 END WHERE id=?');$q->execute([$id]);bump();json_out(['ok'=>true]); }
    if ($action==='db-table') { $table=$_GET['table']??'reservations';$allowed=['users','rooms','reservations','app_state'];if(!in_array($table,$allowed,true))json_out(['error'=>'Unknown table.'],422);$page=max(0,(int)($_GET['page']??0));$total=(int)$p->query('SELECT COUNT(*) FROM "'.$table.'"')->fetchColumn();$q=$p->prepare('SELECT * FROM "'.$table.'" ORDER BY 1 DESC LIMIT 100 OFFSET ?');$q->bindValue(1,$page*100,PDO::PARAM_INT);$q->execute();$rows=$q->fetchAll();if($table==='users')foreach($rows as &$row)unset($row['password_hash']);json_out(['table'=>$table,'rows'=>$rows,'page'=>$page,'total'=>$total,'pages'=>max(1,(int)ceil($total/100))]); }
    if ($action==='db-update'&&$_SERVER['REQUEST_METHOD']==='POST') { require_super();$table=$_POST['table']??'';$id=(int)($_POST['id']??0);$column=$_POST['column']??'';$value=$_POST['value']??'';$allowed=['rooms'=>['name','location','capacity','active'],'reservations'=>['department','event_title','details','start_at','end_at','urgent','status'],'users'=>['name','email','department','active']];if(!isset($allowed[$table])||!in_array($column,$allowed[$table],true)||$id<1)json_out(['error'=>'This field cannot be edited.'],422);if($table==='reservations'&&$column==='status'&&!in_array($value,['pending','approved','rejected','cancelled'],true))json_out(['error'=>'Invalid status.'],422);if(in_array($column,['active','urgent'],true)&&!in_array((string)$value,['0','1'],true))json_out(['error'=>'Choose a valid on/off value.'],422);if($column==='capacity'&&(!ctype_digit((string)$value)||(int)$value<1))json_out(['error'=>'Capacity must be a positive whole number.'],422);if($column==='email'&&!filter_var($value,FILTER_VALIDATE_EMAIL))json_out(['error'=>'Enter a valid email address.'],422);if($table==='reservations'&&in_array($column,['start_at','end_at','urgent'],true)){$q=$p->prepare('SELECT urgent,start_at,end_at FROM reservations WHERE id=?');$q->execute([$id]);$current=$q->fetch();if($current){$urgent=$column==='urgent'?(int)$value:(int)$current['urgent'];$start=$column==='start_at'?$value:$current['start_at'];$end=$column==='end_at'?$value:$current['end_at'];$a=strtotime($start);$b=strtotime($end);if(!$a||!$b||$b<=$a)json_out(['error'=>'Enter a valid start and end time.'],422);if($urgent&&$b-$a>1800)json_out(['error'=>'Urgent reservations are limited to 30 minutes.'],422);}}if($table==='reservations'&&$column==='status'&&$value==='approved'){$q=$p->prepare('SELECT room_id,start_at,end_at FROM reservations WHERE id=?');$q->execute([$id]);$r=$q->fetch();if($r&&conflict((int)$r['room_id'],$r['start_at'],$r['end_at'],$id))json_out(['error'=>'This would create an overlapping reservation.'],409);}$q=$p->prepare('UPDATE "'.$table.'" SET "'.$column.'"=? WHERE id=?');$q->execute([$value,$id]);bump();json_out(['ok'=>true]); }
    if ($action==='revision') json_out(['revision'=>(int)$p->query('SELECT revision FROM app_state')->fetchColumn()]);
    json_out(['error'=>'Unknown API action.'],404);
}
